from __future__ import annotations

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel


class RespondActivityTaskFailedInput(SdkBaseModel):
    task_token: str = Field(alias="taskToken")
    """The taskToken of the ActivityTask. taskToken is generated by the service and should be treated as an opaque
    value. If the task is passed to another process, its taskToken must also be passed. This enables it to provide its
    progress and respond with results."""

    reason: Optional[str] = UNSET
    """Description of the error that may assist in diagnostics."""

    details: Optional[str] = UNSET
    """Detailed information about the failure."""


class RespondActivityTaskFailedInputDict(TypedDict):
    task_token: str
    reason: NotRequired[str]
    details: NotRequired[str]
